183	Vec3 Halfedge_Mesh::Vertex::normal() const {
184		Vec3 n = Vec3(0.0f, 0.0f, 0.0f);
185		Vec3 pi = position;
186		HalfedgeCRef h = halfedge;
187		//walk clockwise around the vertex:
188		do {
