48	Halfedge_Mesh::VertexRef Halfedge_Mesh::emplace_vertex() {
49		VertexRef vertex;
50		if (free_vertices.empty()) {
51			//allocate a new vertex:
52			vertex = vertices.emplace(vertices.end(), Vertex(next_id++));
53		} else {
54			//recycle vertex from free list:
55			vertex = free_vertices.begin();
56			vertices.splice(vertices.end(), free_vertices, free_vertices.begin());
57			*vertex = Vertex(next_id++); //set to default values
58		}
59		//make sure vertex doesn't reference anything:
60		vertex->halfedge = halfedges.end();
61		return vertex;
62	}
