80	Halfedge_Mesh::FaceRef Halfedge_Mesh::emplace_face(bool boundary) {
81		FaceRef face;
82		if (free_faces.empty()) {
83			//allocate a new face:
84			face = faces.emplace(faces.end(), Face(next_id++, boundary));
85		} else {
86			//recycle face from free list:
87			face = free_faces.begin();
88			faces.splice(faces.end(), free_faces, free_faces.begin());
89			*face = Face(next_id++, boundary); //set to default values
90		}
