496				v_target_to_source.insert({*target_id, v});
497			} else {
498				return "Source vertex set is not a subset of target vertex set!";
499			}
500		}
501	
502		for (VertexCRef v = target.vertices.begin(); v != target.vertices.end(); v++) {
503			if (auto source_id = source_verts.find(v->position)) {
504				v_source_to_target.insert({*source_id, v});
505			} else {
