	VertexRef b = t->vertex;
	HalfedgeRef hb = h->next;  //hb : b -> c
	HalfedgeRef hc = hb->next; //hc : c -> ...
	HalfedgeRef ta = t->next;  //ta : a -> d
	HalfedgeRef td = ta->next; //td : d -> ...
	VertexRef c = hc->vertex;
	VertexRef d = td->vertex;

