	//h becomes d -> c and stays in f; t becomes c -> d and stays in g.
	//f' runs c -> ... -> a -> d -> c (old chain, then ta, then h);
	//g' runs d -> ... -> b -> c -> d (old chain, then hb, then t):
	hp->next = ta;
	ta->next = h;
	h->next = hc;
	h->vertex = d;

	tp->next = hb;
	hb->next = t;
	t->next = td;
